head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.bzProcsNo = "";           // 업무처리번호 — 비면 신규 (AS-IS vBzProcsNo ← parentWin.scwin.clickBzProcsNo, 진입 파라미터 §1.2)
scwin.listBzSeq = "";           // 상장업무일련번호 — 수정은 부모 행, 신규는 법인 선택 결과 (AS-IS vListBzSeq)
scwin.mktTpCd = "";             // 거래시장구분 1: 유가, 2: 코스닥 (AS-IS mktTpCd ← parentWin.rdo_SPOT_ISU_TRD_MKT_TP_CD)
scwin.newSecugrpId = "";        // 신규 증권그룹 기본값 (AS-IS parentWin.cmb_NEW_SECUGRP_ID)
scwin.trJob = "";               // 처리구분 I: 저장, U: 수정 (AS-IS TR_JOB)
scwin.KOREA_CNTR_ISO_CD = "410";    // 본점소재지국가 — 대한민국(액면가 필수)
// 원본 : W-Craft 1차 변환본 ULDSTF05101.xml (meta_asisFileNm ULDSTF05101.gfm — 원본 gfm 은 저장소에 없음) — API 적용까지 마친 개발 사본
/*
 * 화면 동작
 *  - 예비심사(ULDSTF05100) 목록에서 [신규]·행 선택으로 열리는 종류주식 예비심사관리 팝업이다(주권 ST·외국주권 FS·주식예탁증권 DR 공용).
 *  - 업무처리번호가 없으면 신규: [법인 찾기](ULDSTF05108)로 법인을 고르면 법인정보(select-com-info)를 채우고, 입력 후 [저장] → 채번 → insert.
 *  - 업무처리번호가 있으면 수정: 상세(select-one)를 채우고 [수정] → update. 심사팀 부서가 아니면 저장·수정이 잠긴다.
 *  - 증권그룹(FS·DR)에 따라 외국주 관련 항목·라벨을 바꾸고, 무액면여부에 따라 액면가 ↔ 1주당자본금을 바꿔 보인다.
 *  - [종목 찾기](ULDSTF05107)·[위원회결과](ULDSTF05110)·[종류주식](ULDSTF05106)·[첨부파일](ULDSTF05003_FILE) 은 openPopup 의 data 로 넘기고 await 한다.
 *  - 통신은 화면에 적용된 API(경로·method·keyInfo)를 명세로 간주한다(사용자 결정 2026-10-29). 팝업 계약은 kindstk 공통 계약서 기준.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05101/ULDSTF05101.md (§번호는 이 문서의 절)
 */

// 고정값
scwin.JOB_NM = { I : "저장", U : "수정" };
// 저장·수정을 할 수 있는 심사팀 부서코드 (AS-IS 의 depCd != 나열 — 심사1팀·심사2팀 등)
scwin.EXAM_DEP_CD_LIST = ["2500", "2520", "2540", "3300", "3320", "3330", "3E00", "3E10", "3E20", "3E30", "3E40", "2615", "3G20"];
// 상장구분(심사진행상태) 목록 — 예비심사 단계 / 상장 단계(첫 글자가 0 이 아닌 상태) (AS-IS strCbd_INVSTG_PROG_STAT_CD_1·_2)
scwin.INVSTG_PROG_STAT_LIST_PRELM = [
    { value : "01", text : "심사진행" },
    { value : "02", text : "심사완료" },
    { value : "03", text : "심사완료(6개월경과등)" },
    { value : "04", text : "심사연기" },
    { value : "05", text : "심사철회" },
    { value : "06", text : "심사기각" }
];
scwin.INVSTG_PROG_STAT_LIST_LIST = [
    { value : "10", text : "신규상장 - 비상장" },
    { value : "11", text : "신규상장 - 코스닥법인" },
    { value : "21", text : "재상장 - 인적분할" },
    { value : "22", text : "재상장 - 폐지" },
    { value : "23", text : "재상장 - 합병" },
    { value : "24", text : "재상장 - 물적분할" }
];

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
// [위원회결과]·[첨부파일]·[종류주식]은 원본 buttonSet 밖이라 늘 활성이다(§4).
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update"       // [수정]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05101.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 파라미터 수신 → 달력 바인딩 → 콤보 목록(주거래은행·공통 코드) → 신규 빈 상세 또는 상세 조회 → 증권그룹별 화면.
 * 증권그룹별 화면은 상세를 받은 뒤에 정한다(원본은 상세 조회를 기다리지 않아 FS·DR 수정 건의 라벨이 바뀌지 않았다 — §8 #1). (§3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 진입 파라미터 — 원본은 부모 컴포넌트·scwin 을 직접 읽었다(getParent) → data 로 받는다(§1.2)
    const param = $c.data.getParameter() ?? {};
    scwin.bzProcsNo = String(param.bzProcsNo ?? "");
    scwin.listBzSeq = String(param.listBzSeq ?? "");
    scwin.mktTpCd = String(param.mktTpCd ?? "");
    scwin.newSecugrpId = String(param.newSecugrpId ?? "");

    // 2) 달력 검사 바인딩(1회) — 단일 달력은 checkCalendarFormat, 기간 쌍은 compareFromToDate 만(규칙 37)
    $c.date.checkCalendarFormat(edt_FOUND_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_ASSO_REG_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_INVSTG_BILL_ACPT_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_LIST_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_LIST_DELIB_SCHDL_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_LIST_DELIB_SCHDL_NOTI_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_INVSTG_COMPLT_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_SECU_STAT_SUBMIT_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_SECU_STAT_EFCT_OCCR_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(txb_CMSTK_LIST_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_LIST_COMITE_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_DFC_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_LIST_FORN_EXCH_LIST_DD1, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_LIST_FORN_EXCH_LIST_DD2, "yyyyMMdd");
    $c.date.compareFromToDate(edt_SUBS_STRT_DD, edt_SUBS_END_DD, ["청약개시일", "청약종료일"]);

    // 3) 콤보 목록 — 주거래은행, 공통 코드(통화·명의개서대리인·외부감사인) (원본 fn_SetComboCode → fn_searchCode)
    await scwin.selectMaintrBk();
    await scwin.selectCodeList();

    // 4) 신규면 빈 상세, 수정이면 상세 조회
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        scwin.initItem();
    } else {
        await scwin.selectDetail();
    }

    // 5) 증권그룹별 라벨·외국주 항목 (원본 fn_initLabel)
    scwin.setComponentBySecugrp(dma_Item.get("secugrpId"));
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_COM_NM_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 법인 찾기(돋보기) 버튼 클릭 — 신규일 때만 활성 (원본 img_COM_NM_onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_COM_NM_onclick = async function (e) {
    try {
        await scwin.openIsurPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05101.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_SEARCH_ISU_CD_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 찾기(돋보기) 버튼 클릭 (원본 img_SEARCH_ISU_CD_onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_SEARCH_ISU_CD_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05101.img_SEARCH_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name scwin.cmb_NPARVALSTK_YN_onviewchange
 * @author Inswave
 * @date 2026. 10. 29
 * @description 무액면여부 선택 — 액면가 ↔ 1주당자본금을 바꿔 보이고, 가려지는 칸은 0 으로 둔다. (원본 cmb_NPARVALSTK_YN_OnSelChange)
 * @param {Object} info 이벤트 정보 객체
 * @returns
 * @hidden N
 */
scwin.cmb_NPARVALSTK_YN_onviewchange = async function (info) {
    try {
        scwin.applyNparvalView(true);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05101.cmb_NPARVALSTK_YN_onviewchange" });
    }
};

