///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectMaintrBk
 * @author Inswave
 * @date 2026. 10. 29
 * @description 주거래은행 목록 조회 (원본 fn_SetComboCode 의 sbm_list-maintrade-bank — §5.1)
 * @returns {Boolean} 조회 성공 여부
 * @hidden N
 */
scwin.selectMaintrBk = async function () {
    const sbmOptions = {
        id : "sbm_selectMaintrBk",
        method : "get",
        action : "/api/listing/common/code/list-maintrade-bank",
        target : "dlt_maintrBkCd=body",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    return result?.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectCodeList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공통 코드 조회 — 통화ISO코드·명의개서대리인·외부감사인을 한 번에 받는다.
 * 원본은 같은 action 8건을 setCommonCode 옵션으로 넘겼는데 setCommonCode 는 action 을 무시해 동작하지 않았다(§8 #2, 계약서 §4.5). (원본 fn_searchCode — §5.2)
 * @returns {Boolean} 조회 성공 여부
 * @hidden N
 */
scwin.selectCodeList = async function () {
    dma_codReq.set("codeList", "CURR_ISO_CD, TRANSSTK_AGNT_CD, EXT_AUDTR_CD");
    const sbmOptions = {
        id : "sbm_selectCodeList",
        method : "get",
        action : "/api/listing/common/code/list-code-value",
        ref : "dma_codReq",
        target : "dlt_currIsoCd=body.CURR_ISO_CD, dlt_transstkAgntCd=body.TRANSSTK_AGNT_CD, dlt_extAudtrCd=body.EXT_AUDTR_CD",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    return result?.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 예비심사 상세 조회 — 상세를 채우고 상장구분 목록·체크·무액면·버튼 상태를 맞춘다. (원본 fn_read_sync — §5.3)
 * @returns {Boolean} 조회 성공 여부
 * @hidden N
 */
scwin.selectDetail = async function () {
    const sbmOptions = {
        id : "sbm_selectDetail",
        method : "get",
        action : "/api/listing/lstproc/kind/prelisting-kindstk/select-one",
        target : "dma_Item=body",
        isProcessMsg : false
    };
    const requestData = {
        bzProcsNo : scwin.bzProcsNo,
        listBzSeq : scwin.listBzSeq,
        spotIsuTrdMktTpCd : scwin.mktTpCd
    };
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.responseJSON?.success !== true) return false;

    dma_Item.set("bzProcsNo", scwin.bzProcsNo);
    dma_Item.set("listBzSeq", scwin.listBzSeq);
    scwin.setInvstgProgStatList(dma_Item.get("invstgProgStatCd"));
    // 비공개 심사 체크는 값이 반대 — 체크 = webDpYn "N" (원본 chk_WEB_DP_YN)
    chk_WEB_DP_YN.setValue((dma_Item.get("webDpYn") === "N") ? "Y" : "");
    scwin.applyNparvalView(false);
    scwin.setIsurSearchEnabled(false);
    scwin.applyButtonState();
    return true;
};

/**
 * @method
 * @name scwin.selectComInfo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 고른 법인의 법인정보를 상세에 채운다. (원본 fn_SetParIsur 의 sbm_selectcominfo — §5.4)
 * @param {String} isurCd 법인코드
 * @returns {Boolean} 조회 성공 여부
 * @hidden N
 */
scwin.selectComInfo = async function (isurCd) {
    const sbmOptions = {
        id : "sbm_selectComInfo",
        method : "get",
        action : "/api/listing/lstproc/kind/prelisting-kindstk/select-com-info",
        target : "dma_Item=body",
        isProcessMsg : false
    };
    const requestData = {
        isurCd : isurCd,
        listBzSeq : scwin.listBzSeq
    };
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    return result?.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 예비심사 저장(insert)·수정(update). 성공하면 안내 후 상세를 다시 조회한다. (원본 fn_trs — §5.5)
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns {Boolean} 처리 성공 여부
 * @hidden N
 */
scwin.saveTrs = async function (trJob) {
    const jobNm = scwin.JOB_NM[trJob] ?? "";
    const empNo = $c.session.getUserInfo("empNo");

    // 원본 fn_trs — 심사담당자·최초심사담당자 = 로그인 사용자, 체크 2개는 저장값으로 바꿔 넣는다
    dma_Item.set("examprnEmpNo", empNo);
    dma_Item.set("fstExamprnEmpNo", empNo);     // TODO: 수정 때도 최초심사담당자를 덮어쓴다(원본과 같음) — 서버가 무시하는지 확인 (§10 #4)
    dma_Item.set("webDpYn", (chk_WEB_DP_YN.getValue() === "Y") ? "N" : "Y");
    dma_Item.set("webNopnYn", (chk_WEB_NOPN_YN.getValue() === "Y") ? "Y" : "N");
    dma_Item.set("spotIsuTrdMktTpCd", scwin.mktTpCd);

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/kind/prelisting-kindstk/insert"
                                 : "/api/listing/lstproc/kind/prelisting-kindstk/update",
        ref : "dma_Item",
        mediatype : "application/json",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;      // 진행 중 처리가 있어 이번 호출은 건너뜀

    // 응답 body.result 가 "S" 일 때만 성공 (원본과 같음)
    if (result?.responseJSON?.success !== true || result?.responseJSON?.body?.result !== "S") {
        await $c.win.alert($c.data.getMessage("com_complete_0151", jobNm));     // "$[0] 처리 실패하였습니다."
        return false;
    }

    await $c.win.alert($c.data.getMessage("com_complete_0150", jobNm));         // "$[0] 처리 성공하였습니다."
    scwin.bzProcsNo = String(dma_Item.get("bzProcsNo") ?? "");                   // 저장이면 채번한 번호로 수정 모드가 된다
    await scwin.selectDetail();
    // 원본은 여기서 부모 목록을 다시 조회했다(fn_parentRefresh) → 부모가 팝업이 닫힌 뒤 재조회한다(계약서 §2 부모 재조회 규약)
    return true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initItem
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 빈 상세 — 증권그룹 기본값(부모 신규 증권그룹), 신규 기본값, 법인 찾기 활성, insert 버튼 상태. (원본 init 의 else 분기 — §3)
 * @returns
 * @hidden N
 */
scwin.initItem = function () {
    dma_Item.setEmptyValue();
    dma_Item.set("secugrpId", scwin.newSecugrpId);
    scwin.applyNewDefaults();
    chk_WEB_DP_YN.setValue("");
    scwin.setIsurSearchEnabled(true);
    scwin.applyButtonState();
};

/**
 * @method
 * @name scwin.applyNewDefaults
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 기본값 — 비어 있는 것만 채운다: 상장구분 「심사진행(01)」, 무액면여부 「아니오(N)」, 상장일시초가·상장일종가 0.
 * 원본은 init 에서 채운 뒤 법인을 고르면 dma_Item 을 비워 상장구분이 사라졌다(§8 #4). (원본 fn_changeForm("01")·fn_initLabel 의 0 설정)
 * @returns
 * @hidden N
 */
scwin.applyNewDefaults = function () {
    scwin.setInvstgProgStatList(dma_Item.get("invstgProgStatCd") || "01");
    if ($c.util.isEmpty(dma_Item.get("nparvalstkYn"))) dma_Item.set("nparvalstkYn", "N");
    if ($c.util.isEmpty(dma_Item.get("fstBasPrc"))) dma_Item.set("fstBasPrc", 0);
    if ($c.util.isEmpty(dma_Item.get("listddClsprc"))) dma_Item.set("listddClsprc", 0);
    scwin.applyNparvalView(false);
};

/**
 * @method
 * @name scwin.setInvstgProgStatList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장구분 콤보 목록을 상태에 맞게 바꾸고 값을 고른다 — 첫 글자가 0 이 아니면 상장 단계 목록, 아니면 예비심사 단계 목록. (원본 fn_changeForm)
 * @param {String} statCd 심사진행상태코드
 * @returns
 * @hidden N
 */
scwin.setInvstgProgStatList = function (statCd) {
    const code = String(statCd ?? "");
    const isListStep = (code !== "" && code.charAt(0) !== "0");
    dlt_invstgProgStatCd.setJSON(isListStep ? scwin.INVSTG_PROG_STAT_LIST_LIST : scwin.INVSTG_PROG_STAT_LIST_PRELM);
    cmb_INVSTG_PROG_STAT_CD.setDisabled(false);
    cmb_INVSTG_PROG_STAT_CD.setValue(code);
};

/**
 * @method
 * @name scwin.setIsurSearchEnabled
 * @author Inswave
 * @date 2026. 10. 29
 * @description 법인 찾기 버튼 활성/비활성 — 신규만 법인을 고를 수 있다. (원본 fn_initForm "C"/"X" — 버튼 이미지 교체는 setDisabled 로)
 * @param {Boolean} enabled 활성 여부
 * @returns
 * @hidden N
 */
scwin.setIsurSearchEnabled = function (enabled) {
    img_COM_NM.setDisabled(!enabled);
};

/**
 * @method
 * @name scwin.setComponentBySecugrp
 * @author Inswave
 * @date 2026. 10. 29
 * @description 증권그룹별 라벨·외국주 항목 표시. FS 는 당기순이익(외화)·통화 항목, DR 은 DR 라벨·1DR당 원주비율, 그 밖(ST)은 외국주 항목 잠금.
 * 상장일시초가·상장일종가 0 설정은 신규 기본값(applyNewDefaults)으로 옮겼다(§8 #1). (원본 fn_initLabel)
 * @param {String} secugrpId 증권그룹ID ST·FS·DR
 * @returns
 * @hidden N
 */
scwin.setComponentBySecugrp = function (secugrpId) {
    // 필수 표시(*)는 라벨의 req class 가 보인다 — 원본의 "*상장(예정)주식수" 접두는 쓰지 않는다
    lb_LIST_SHRS.setValue("상장(예정)주식수");
    lb_PARVAL.setValue("액면가");
    lb_PUBOFR_SHRS.setValue("공모주식수");
    label_59.hide();
    label_78.hide();
    label_79.hide();
    label_81.hide();
    edt_NETINCM_AMT1.hide();
    cmb_NETINCM_CURR_ISO_CD.hide();

    if (secugrpId === "FS") {
        panel_foriegn.setDisabled(false);
        panel_foriegn.setReadOnly(false);
        label_47.hide();
        label_80.hide();
        label_78.show();
        label_79.show();
        label_81.show();
        label_dr.show();
        edt_NETINCM_AMT1.show();
        cmb_NETINCM_CURR_ISO_CD.show();
        panel_Forn_Item.show("");
        cmb_CURR_ISO_CD.hide();
        edt_PER1DR_FORNSTK_RTO.setDisabled(true);
        if ($c.util.isEmpty(cmb_PUBPRC_CURR_ISO_CD.getValue())) cmb_PUBPRC_CURR_ISO_CD.setValue("KRW");
        if ($c.util.isEmpty(cmb_PUBPRC_SCHDL_CURR_ISO_CD.getValue())) cmb_PUBPRC_SCHDL_CURR_ISO_CD.setValue("KRW");
        return;
    }

    if (secugrpId === "DR") {
        panel_foriegn.setDisabled(false);
        panel_foriegn.setReadOnly(false);
        label_74.hide();
        label_75.hide();
        label_76.hide();
        label_77.hide();
        label_59.show();
        label_dr.show();
        cmb_PARVAL_CURR_ISO_CD.hide();
        cmb_FNC_CURR_ISO_CD.hide();
        cmb_PUBPRC_CURR_ISO_CD.hide();
        cmb_PUBPRC_SCHDL_CURR_ISO_CD.hide();
        cmb_NETINCM_CURR_ISO_CD.hide();
        panel_Forn_Item.show("");
        edt_PER1DR_FORNSTK_RTO.setDisabled(false);
        lb_LIST_SHRS.setValue("상장DR수");
        lb_PARVAL.setValue("액면가(원주기준)");
        lb_PUBOFR_SHRS.setValue("공모DR수");
        return;
    }

    panel_foriegn.setDisabled(true);
    panel_foriegn.setReadOnly(true);
    label_dr.hide();
    panel_Forn_Item.hide();
};

/**
 * @method
 * @name scwin.applyNparvalView
 * @author Inswave
 * @date 2026. 10. 29
 * @description 무액면여부에 따라 액면가 ↔ 1주당자본금을 바꿔 보인다. reset 이면 가려지는 칸을 0 으로 둔다(사용자가 바꿀 때만).
 * (원본 init·fn_read_sync·cmb_NPARVALSTK_YN_OnSelChange 의 같은 분기 3벌을 하나로)
 * @param {Boolean} reset 가려지는 칸을 0 으로 둘지
 * @returns
 * @hidden N
 */
scwin.applyNparvalView = function (reset) {
    const isNparval = (cmb_NPARVALSTK_YN.getValue() === "Y");
    if (isNparval) {
        edt_PARVAL.hide();
        lb_PARVAL.hide();
        edt_PER1STK_CAP.show("");
        lb_PER1STK_CAP.show("");
        if (reset) dma_Item.set("parval", 0);
    } else {
        edt_PARVAL.show("");
        lb_PARVAL.show("");
        edt_PER1STK_CAP.hide();
        lb_PER1STK_CAP.hide();
        if (reset) dma_Item.set("per1stkCap", 0);
    }
};

/**
 * @method
 * @name scwin.isExamDept
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로그인 사용자가 저장·수정을 할 수 있는 심사팀 부서인지 (원본 depCd != 나열 조건)
 * @returns {Boolean} 심사팀 부서 여부
 * @hidden N
 */
scwin.isExamDept = function () {
    return scwin.EXAM_DEP_CD_LIST.includes(String($c.session.getUserInfo("depCd") ?? ""));
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 29
 * @description 버튼 상태 — 신규 insert(저장), 수정 update(수정), 심사팀 부서가 아니면 error(둘 다 잠금). (원본 init·fn_read_sync 의 setButtonState)
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    const state = $c.util.isEmpty(scwin.bzProcsNo) ? "insert" : "update";
    $c.util.setButtonState("grp_btnBox", scwin.isExamDept() ? state : "error", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장·수정 전 검증. 조건부 필수(증권그룹·국가)와 버튼 포커스가 섞여 순서대로 검사한다(규칙 24 판단 — §6.6).
 * 원본의 주석 처리된 검사(청구서접수일·심사결과확정일·상장주식수·액면가 통화)는 옮기지 않는다(규칙 0). (원본 fn_CheckForm)
 * @returns {Boolean} 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    if ($c.util.isEmpty(txb_ISUR_CD.getValue())) {
        await $c.win.alert("[법인]을 선택하세요.");
        img_COM_NM.focus();
        return false;
    }
    const comNm = String(txb_COM_NM.getValue() ?? "");
    if ($c.util.isEmpty(comNm)) {
        await $c.win.alert("[한글법인명]을 입력하세요..");
        txb_COM_NM.focus();
        return false;
    }

    // 2009.05.12 국내법인(ST)은 '주식회사' 대신 '(주)' 로 입력
    if (dma_Item.get("secugrpId") === "ST") {
        if (comNm.includes("주식회사")) {
            await $c.win.alert("한글회사명에 '주식회사'는 '(주)'로 입력, 영문회사명에 'CO.,LTD' 를 입력하세요");
            txb_COM_NM.focus();
            return false;
        }
        if (!comNm.includes("(주)")) {
            await $c.win.alert("한글회사명에 '(주)' 를 입력하세요");
            txb_COM_NM.focus();
            return false;
        }
    }

    if ($c.util.isEmpty(txb_COM_ENG_NM.getValue())) {
        await $c.win.alert("[영문법인명]을 입력하세요..");
        txb_COM_ENG_NM.focus();
        return false;
    }
    if (chk_WEB_DP_YN.getValue() === "Y" && chk_WEB_NOPN_YN.getValue() === "Y") {
        await $c.win.alert("[비공개 심사시 선택] 와 [비공개(인적분할 재상시)]를 중복으로 선택하실수 없습니다.");
        chk_WEB_DP_YN.focus();
        return false;
    }
    if ($c.util.isEmpty(txb_APPL_COM_CHRG_NM.getValue())) {
        await $c.win.alert("신청회사 담당자명을 입력하십시오");
        txb_APPL_COM_CHRG_NM.focus();
        return false;
    }
    if ($c.util.isEmpty(txb_APPL_COM_CHRG_TEL_NO.getValue())) {
        await $c.win.alert("담당자 연락처를 입력하십시오");
        txb_APPL_COM_CHRG_TEL_NO.focus();
        return false;
    }
    if ($c.util.isEmpty(cmb_INVSTG_PROG_STAT_CD.getValue())) {
        await $c.win.alert("[심사상태]을 선택하세요.");
        cmb_INVSTG_PROG_STAT_CD.focus();
        return false;
    }

    if (dma_Item.get("secugrpId") === "FS") {
        if ($c.util.isEmpty(edt_NETINCM_AMT.getValue())) {
            await $c.win.alert("[당기순이익(원화)]를 입력하세요.");
            edt_NETINCM_AMT.focus();
            return false;
        }
        if ($c.util.isEmpty(edt_NETINCM_AMT1.getValue())) {
            await $c.win.alert("[당기순이익(외화)]를 입력하세요.");
            edt_NETINCM_AMT1.focus();
            return false;
        }
        if ($c.util.isEmpty(cmb_NETINCM_CURR_ISO_CD.getValue())) {
            await $c.win.alert("[당기순이익(외화) 통화표시]를 입력하세요.");
            cmb_NETINCM_CURR_ISO_CD.focus();
            return false;
        }
    } else if ($c.util.isEmpty(edt_NETINCM_AMT.getValue())) {
        await $c.win.alert("[당기순이익]을 입력하세요.");
        edt_NETINCM_AMT.focus();
        return false;
    }

    // 본점소재지국가가 대한민국이면 액면가 필수 — 원본 parseInt 진법 18 은 10 으로 고침(§8 #6)
    if (txb_CNTR_ISO_CD.getValue() === scwin.KOREA_CNTR_ISO_CD) {
        const parval = String(edt_PARVAL.getValue() ?? "");
        if ($c.util.isEmpty(parval) || parseInt(parval, 10) <= 0) {
            await $c.win.alert("[액면가]를 입력하세요.");
            edt_PARVAL.focus();
            return false;
        }
    }

    // 원본은 안내 후에도 저장을 계속했다 → 멈춘다(§8 #5)
    if ($c.util.isEmpty(txb_ISU_NM.getValue())) {
        await $c.win.alert("[종목명]를 입력하세요.");
        txb_ISU_NM.focus();
        return false;
    }

    return true;
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 업무처리번호 채번 — pcc $c.stf.getNewBzProcNo 응답에서 번호를 꺼낸다(body 가 문자열 / { bzProcsNo } 모두 받는다).
 * @returns {String} 업무처리번호 (14자리가 정상)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    // TODO: 채번 응답 모양 미확정 — body 가 문자열인지 { bzProcsNo } 인지 확인 (§10 #3). 지금은 둘 다 받는다.
    const res = await $c.stf.getNewBzProcNo();
    const body = res?.body ?? res;
    return String((typeof body === "object" && body !== null) ? (body.bzProcsNo ?? "") : (body ?? ""));
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장(신규) — 검증 → 확인 → 채번(14자리) → insert. 원본은 채번 값을 바로 vBzProcsNo 에 넣어 실패해도 수정 모드처럼 남았다 → 성공 뒤에만 바꾼다(§8 #7). (원본 fn_save)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";
    if (!await scwin.validate()) return;
    if (!await $c.lc.isProcess(scwin.trJob)) return;       // "[저장] 처리를 하시겠습니까?" (MSG-A006)

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if ($c.str.getByteLength(bzProcsNo) !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    dma_Item.set("bzProcsNo", bzProcsNo);
    if (!await scwin.saveTrs(scwin.trJob)) dma_Item.set("bzProcsNo", "");
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정 — 검증 → 확인 → update. (원본 fn_update)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";
    if (!await scwin.validate()) return;
    if (!await $c.lc.isProcess(scwin.trJob)) return;       // "[수정] 처리를 하시겠습니까?" (MSG-A006)
    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.openIsurPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 예비심사 법인 선택 팝업(ULDSTF05108)을 data 로 열고, 고른 법인으로 법인정보를 채운다.
 * (원본 img_COM_NM_onclick → fn_GetPar/fn_SetPar 바꿔 끼우기 + fn_PopFindKindStkExamCorp — 계약서 05108, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.openIsurPopup = async function () {
    const secugrpId = String(cmb_SECUGRP_ID.getValue() ?? "");
    if ($c.util.isEmpty(secugrpId)) {
        await $c.win.alert("[유가증권]을 선택하세요.");
        return;
    }

    const options = {
        id : "ULDSTF05108",
        popupName : $c.lc.getSecuGrpNm(secugrpId) + " 종류주식 예비심사 법인 선택",
        width : 1180,
        height : 880,
        frameModal : "top"
    };
    const data = {
        isurCd : txb_ISUR_CD.getValue(),
        comNm : txb_COM_NM.getValue(),
        secugrpId : secugrpId,
        mktTpCd : scwin.mktTpCd,
        searchType : $c.lc.getGlbValue("SEARCH_TYP_SEC")        // 유가예비심사신규등록 (원본 $c.lc.SEARCH_TYP_SEC 는 미정의)
    };
    const res = await $c.win.openPopup("/ui/lst/kindstk/ULDSTF05108.xml", options, data);
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.isurCd)) return;

    await scwin.setIsur(res);
};

/**
 * @method
 * @name scwin.setIsur
 * @author Inswave
 * @date 2026. 10. 29
 * @description 법인 선택 결과 반영 — 상세를 비우고 법인정보(select-com-info)를 받은 뒤, 응답에 없는 값은 선택 결과·신규 기본값으로 채운다.
 * (원본 fn_SetParIsur — 원본은 값을 넣은 뒤 setEmptyValue 로 지워 응답 값만 남았다, §8 #4)
 * @param {Object} res 05108 반환 { isurCd, comNm, listDd, listBzSeq, dbClickYn }
 * @returns
 * @hidden N
 */
scwin.setIsur = async function (res) {
    scwin.listBzSeq = String(res.listBzSeq ?? "");
    dma_Item.setEmptyValue();

    // 조회 실패면 비운 상세에 증권그룹까지 사라지므로 신규 빈 상세로 되돌린다
    if (!await scwin.selectComInfo(res.isurCd)) {
        scwin.initItem();
        return;
    }

    if ($c.util.isEmpty(dma_Item.get("isurCd"))) dma_Item.set("isurCd", res.isurCd);
    if ($c.util.isEmpty(dma_Item.get("comNm"))) dma_Item.set("comNm", res.comNm ?? "");
    if ($c.util.isEmpty(dma_Item.get("cmstkListDd"))) dma_Item.set("cmstkListDd", res.listDd ?? "");      // 보통주상장일 (원본 txb_CMSTK_LIST_DD ← LIST_DD)
    if ($c.util.isEmpty(dma_Item.get("secugrpId"))) dma_Item.set("secugrpId", scwin.newSecugrpId);      // 원본은 부모 cmb_NEW_SECUGRP_ID 를 직접 읽었다
    dma_Item.set("listBzSeq", scwin.listBzSeq);
    scwin.applyNewDefaults();
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 예비심사 종목 선택 팝업(ULDSTF05107)을 data 로 열고 고른 종목을 종목코드·종목명에 넣는다. 법인을 먼저 골라야 한다.
 * 원본은 부모(05100) 컴포넌트에서 증권그룹·시장을 읽었다 → 이 화면 값으로 넘긴다(계약서 05107). (원본 img_SEARCH_ISU_CD_onclick → fn_PopFindKindStkExamIsu)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    if ($c.util.isEmpty(txb_ISUR_CD.getValue())) {
        await $c.win.alert("회사를 선택해 주세요");
        return;
    }

    const options = {
        id : "ULDSTF05107",
        popupName : "종류주식 예비심사 종목 선택",
        width : 800,
        height : 780,
        frameModal : "top",
        type : "pageFramePopup"
    };
    const data = {
        isurCd : txb_ISUR_CD.getValue(),
        secugrpId : cmb_SECUGRP_ID.getValue(),
        mktTpCd : scwin.mktTpCd,
        searchType : $c.lc.getGlbValue("SEARCH_TYP_SER")        // 유가예비심사등록조회
    };
    const res = await $c.win.openPopup("/ui/lst/kindstk/ULDSTF05107.xml", options, data);
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.isuCd)) return;

    dma_Item.set("isuCd", res.isuCd);
    dma_Item.set("isuNm", res.isuNm ?? "");
};

/**
 * @method
 * @name scwin.openInvRstPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종류주식 위원회결과 팝업(ULDSTF05110)을 data 로 연다. 저장했거나 창을 닫으면 상세를 다시 조회한다(계약서 부모 재조회 규약).
 * 예비심사를 저장한 뒤에만 연다(원본은 막지 않았다 — §8 #8). (원본 fn_GetParDtl + fn_OpenInvRst)
 * @returns
 * @hidden N
 */
scwin.openInvRstPopup = async function () {
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        await $c.win.alert("저장버튼을 클릭하여 예비심사를 작성한 후 클릭하십시오");
        return;
    }

    const options = {
        id : "ULDSTF05110",
        popupName : "종류주식 위원회결과",
        width : 800,
        height : 580,
        frameModal : "top"
    };
    const data = {
        isurCd : txb_ISUR_CD.getValue(),
        bzProcsNo : scwin.bzProcsNo,
        comNm : txb_COM_NM.getValue()
    };
    const res = await $c.win.openPopup("/ui/lst/kindstk/ULDSTF05110.xml", options, data);
    if (res?.isSaved === true || res?.isCloseButtonClick === true) {
        await scwin.selectDetail();
    }
};

/**
 * @method
 * @name scwin.openKindStkPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종류주식상세 팝업(ULDSTF05106)을 data 로 열고 닫힐 때까지 기다린다(반환 없음). 예비심사를 저장한 뒤에만 연다.
 * (원본 btn_kindStk_onclick — 원본 키 vBzProcsNo·vListProcsStatCd·vPRELM_INVSTG_BZ_PROCS_NO 는 camelCase 로, 계약서 05106)
 * @returns
 * @hidden N
 */
scwin.openKindStkPopup = async function () {
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        await $c.win.alert("저장버튼을 클릭하여 예비심사를 작성한 후 클릭하십시오");
        return;
    }

    const options = {
        id : "ULDSTF05106",
        popupName : "종류주식 상세",
        width : 1135,
        height : 840,
        frameModal : "top",
        type : "pageFramePopup"
    };
    const data = {
        bzProcsNo : scwin.bzProcsNo,
        listProcsStatCd : dma_Item.get("invstgProgStatCd"),
        prelmInvstgBzProcsNo : "",      // TODO: 예비심사 화면에서는 넘길 값이 없다(원본도 "") — 05106 이 비어도 되는지 확인 (§10 #6)
        mktTpCd : scwin.mktTpCd
    };
    await $c.win.openPopup("/ui/lst/kindstk/ULDSTF05106.xml", options, data);
};

/**
 * @method
 * @name scwin.openFilePopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 예비심사 첨부파일등록 팝업(ULDSTF05003_FILE)을 연다. (원본 fn_FileAdd — 2009.02.10 첨부파일추가)
 * @returns
 * @hidden N
 */
scwin.openFilePopup = async function () {
    const options = {
        id : "ULDSTF05003_FILE",
        popupName : "예비심사 첨부파일등록",
        width : 740,
        height : 370,
        frameModal : "top"
    };
    // TODO: 05003_FILE 은 저장소에 전환본이 없다 — 경로·수신 키(gBzProcsNo)는 원본 그대로 (§10 #5)
    await $c.win.openPopup("/ui/lst/lstproc/ULDSTF05003_FILE.xml", options, { gBzProcsNo : scwin.bzProcsNo });
};
